    }

    // ========================================================================
    // SECTION 9: CONTEXT
    // ========================================================================
    context: {
        related_files: [
            {
                path:      "crates/intent-cli/src/main.rs"
                relevance: "Entry point that calls Cli::parse() and dispatch()"
